1	import { failureLine, runEntire } from './entire-cli.mjs'
2	import { diffStat, safeRef } from './git.mjs'
3	import { serverHost, workspaceHost } from './hosts.mjs'
4	import { serverSshTarget } from './ssh-targets.mjs'
5	import { trailSummary } from './trail.mjs'
6	import { resolveFocusedWorkspace } from './workspace.mjs'
7	
8	const VERSION = { key: 'version', label: 'Entire CLI', args: ['--version'], parse: (out) => out.trim().split('\n')[0] }
9	
10	// Each step keeps its own outcome, so one failed call (a branch without a trail, say) hides nothing else.
11	// `byRepo` steps read Entire's server and also work for a paired server's workspace, given --repo and
12	// --branch; the others read the checkout, which for a paired server means over SSH.
13	const STEPS = [
14	  {
15	    key: 'status',
16	    label: 'Repo',
17	    args: ['status', '--json'],
18	    parse: JSON.parse,
19	    summarize: (status) =>
20	      status.enabled ? `enabled · agents: ${(status.agents ?? []).join(', ') || 'none'}` : 'Entire is not enabled here'
21	  },
22	  // A branch without a trail is normal, so this step reports instead of failing the check.
23	  {
24	    key: 'trail',
25	    label: 'Trail',
26	    args: ['trail', 'show', '--json'],
27	    byRepo: true,
28	    optional: true,
29	    parse: JSON.parse,
30	    summarize: (trail) => `#${trail.number} ${trail.title} · ${trail.status}`
31	  },
32	  {
33	    key: 'checkpoints',
34	    label: 'Checkpoints',
35	    args: ['checkpoint', 'list', '--json'],
36	    parse: JSON.parse,
37	    summarize: (list) => `${list.length} on this branch`
38	  }
39	]
40	
41	// Fetched alongside the steps for the panel only: the connection check doesn't report them. Every status,
42	// so resolved findings and how they were fixed show too, as in Entire's web view.
43	const FINDINGS = {
44	  key: 'findings',
45	  label: 'Findings',
46	  args: ['trail', 'finding', 'list', '--status', 'any', '--freshness', 'any', '--json'],
47	  byRepo: true,
48	  parse: JSON.parse
49	}
50	
51	// The panel keeps the newest checkpoints only.
52	const CHECKPOINT_LIMIT = 20
53	
54	// The focused workspace and where Entire runs for it: { workspace, host, problem }. With a problem the
55	// host is null, and the workspace too when there is none to describe.
56	export async function focusedHost(orca, { signal } = {}) {
57	  let resolved
58	  try {
59	    resolved = await resolveFocusedWorkspace(orca, { signal })
60	  } catch (error) {
61	    return { workspace: null, host: null, problem: `Workspace lookup failed: ${error.message}` }
62	  }
63	  const { context, path, via, candidates, server, unreachable = [] } = resolved
64	  if (!context) return { workspace: null, host: null, problem: 'No workspace is focused' }
65	  const workspace = {
66	    // Orca's id for the workspace, when it gives one; the panel picks the focused entry by it.
67	    ...(context.workspaceId ? { id: context.workspaceId } : {}),
68	    name: context.displayName,
69	    branch: context.branch,
70	    terminals: context.terminals.map((terminal) => terminal.id),
71	    path,
72	    via
73	  }
74	  if (!path) return { workspace, host: null, problem: unresolved(context, via, candidates, unreachable) }
75	
76	  let host = workspaceHost(path)
77	  if (server) {
78	    let target = null
79	    let remoteProblem = null
80	    try {
81	      target = await serverSshTarget(server.environment, { signal })
82	    } catch (error) {
83	      remoteProblem = error.message
84	    }
85	    host = serverHost({ ...server, path, target, remoteProblem })
86	    // readContext gives a server workspace's repo name and no branch; the panel shows the real branch.
87	    // repoUrl lets the panel's actions name the repository without resolving focus again.
88	    workspace.server = { environment: server.environment, branch: server.branch, repoUrl: host.repo }
89	    workspace.where = `${server.environment} ${path}`
90	    if (!host.repo) return { workspace, host: null, problem: `${path} on ${server.environment} has no origin remote, so Entire can't tell which repository it is.` }
91	    if (!host.branch) return { workspace, host: null, problem: `${path} on ${server.environment} is on no branch (detached HEAD?), so Entire has no trail to look up.` }
92	  } else {
93	    workspace.where = host.kind === 'wsl' ? `WSL ${host.distro} ${host.path}` : path
94	  }
95	  return { workspace, host, problem: null }
96	}
