98	// Everything the panel and "Entire: Check connection" show for the focused workspace.
99	export async function collectSnapshot(orca, { signal } = {}) {
100	  const snapshot = { at: new Date().toISOString(), workspace: null, problem: null, steps: [], data: {} }
101	  const { workspace, host, problem } = await focusedHost(orca, { signal })
102	  if (problem) return { ...snapshot, workspace, problem }
103	
104	  const version = await runStep(host, VERSION, signal)
105	  if (!version.ok) return { ...snapshot, workspace, steps: [version.step] }
106	  const [findings, ...results] = await Promise.all([FINDINGS, ...STEPS].map((step) => runStep(host, step, signal)))
107	  const data = Object.fromEntries(results.filter((result) => result.ok).map((result) => [result.step.key, result.value]))
108	  if (data.checkpoints) data.checkpoints = data.checkpoints.slice(0, CHECKPOINT_LIMIT)
109	  if (data.trail) {
110	    const found = findings.ok ? findings.value : null
111	    const base = safeRef(found?.trail?.base)
112	    const checkout = host.kind === 'server' ? host.remote : host
113	    const diff = base && checkout ? await diffStat(checkout, base, { signal }) : null
114	    data.trail = trailSummary(data.trail, { findings: found, diff })
115	  }
116	  return { ...snapshot, workspace, steps: [version.step, ...results.map((result) => result.step)], data }
117	}
