119	function unresolved(context, via, candidates, unreachable) {
120	  const name = context.branch ? `${context.displayName} on ${context.branch}` : context.displayName
121	  const offline = unreachable.length > 0 ? ` (couldn't ask ${unreachable.join('; ')})` : ''
122	  if (via === 'server' && unreachable.length > 0) {
123	    // A server that didn't answer may hold the focused workspace under the same repo name.
124	    const found = candidates.length > 0 ? `${candidates.length} other ${candidates.length === 1 ? 'match' : 'matches'}, but ` : ''
125	    return `${name}: ${found}couldn't ask every paired server, so the focused workspace is unknown${offline}. Use ↻ once it answers.`
126	  }
127	  if (via === 'server' && candidates.length > 1) {
128	    // Orca names only the repo of a paired server's workspace, so its worktrees look alike.
129	    return `${name}: ${candidates.length} workspaces of this repository match on paired servers, and Orca doesn't tell plugins which one is focused.`
130	  }
131	  if (candidates.length > 0) {
132	    // Without a terminal, only branch and name identify the workspace, and many repos share "main".
133	    return `${name}: ${candidates.length} workspaces match it. Open a terminal in it and try again.`
134	  }
135	  return `${name}: no workspace matches it${offline}. Open a terminal in it and try again.`
136	}
137	
138	async function runStep(host, { key, label, args, byRepo = false, optional = false, parse, summarize = (value) => value }, signal) {
139	  const step = { key, label, optional, ok: false }
140	  if (host.kind === 'server' && key !== 'version') {
141	    if (byRepo) args = [...args, '--repo', host.repo, '--branch', host.branch]
142	    else if (host.remote) host = host.remote
143	    // Without SSH only Entire's server is in reach; say so instead of failing.
144	    else return { ok: false, step: { ...step, optional: true, text: `only readable on ${host.environment}, which the plugin can't reach over SSH (${host.remoteProblem ?? 'no SSH target'})` } }
145	  }
146	  let result
147	  try {
148	    result = await runEntire(host, args, { signal })
149	  } catch (error) {
150	    return { ok: false, step: { ...step, text: error.message } }
151	  }
152	  if (result.code !== 0) return { ok: false, step: { ...step, text: explainFailure(host, result), ms: result.ms } }
153	  try {
154	    const value = parse(result.stdout)
155	    return { ok: true, value, step: { ...step, ok: true, text: summarize(value), ms: result.ms } }
156	  } catch {
157	    return { ok: false, step: { ...step, text: `unexpected output: ${result.stdout.slice(0, 120)}`, ms: result.ms } }
158	  }
159	}
160	
161	// Entire answers a repository it doesn't track, or this desktop's login can't see, with a bare 404.
162	function explainFailure(host, result) {
163	  const line = failureLine(result)
164	  if (host.kind === 'server' && /repository not found/i.test(line)) return 'repository not on Entire for this computer’s login'
165	  // ssh exits 255 for its own failures, as opposed to the remote command's.
166	  if (host.kind === 'ssh' && result.code === 255) {
167	    const hint = /permission denied/i.test(line) ? ' Is its key in ssh-agent (ssh-add)?' : ''
168	    return `SSH to ${host.environment} failed: ${line}${hint}`
169	  }
170	  return line
171	}
