1	import { entireCommand } from './hosts.mjs'
2	import { desktopEnv, run } from './process.mjs'
3	
4	export function runEntire(host, args, { signal, timeoutMs } = {}) {
5	  const { command, args: argv, cwd } = entireCommand(host, args)
6	  return run(command, argv, { cwd, env: entireEnv(), signal, timeoutMs })
7	}
8	
9	// Entire sends usage analytics from a detached `entire __send_analytics` child. On Windows that child has
10	// no console, so every git it runs opens a terminal window. The plugin's calls are background reads, so
11	// they opt out of analytics; WSLENV carries the opt-out into WSL as well.
12	export function entireEnv(env = desktopEnv()) {
13	  return {
14	    ...env,
15	    ENTIRE_TELEMETRY_OPTOUT: '1',
16	    WSLENV: env.WSLENV ? `${env.WSLENV}:ENTIRE_TELEMETRY_OPTOUT` : 'ENTIRE_TELEMETRY_OPTOUT'
17	  }
18	}
19	
20	// Entire explains a failure in one line, on stderr or stdout depending on the command.
21	export function failureLine(result) {
22	  if (result.timedOut) return `timed out after ${result.ms} ms`
23	  return (result.stderr.trim() || result.stdout.trim() || `exit ${result.code}`).split('\n')[0]
24	}
