1	import { tmpdir } from 'node:os'
2	
3	// Orca reports WSL workspaces as UNC paths, while the plugin worker always runs on the desktop host.
4	// Entire has to run where the repo and its login live, so each workspace path maps to a host.
5	
6	const WSL_UNC = /^\\\\wsl(?:\.localhost|\$)\\([^\\]+)(\\.*)?$/i
7	
8	export function workspaceHost(workspacePath) {
9	  const match = WSL_UNC.exec(workspacePath.replaceAll('/', '\\'))
10	  if (!match) return { kind: 'local', path: workspacePath }
11	  return { kind: 'wsl', distro: match[1], path: (match[2] ?? '\\').replaceAll('\\', '/') }
12	}
13	
14	// A workspace on a paired Orca server (a VPS). Trails and findings live on Entire's server, so this
15	// desktop's Entire reads them by repository and branch. Status, checkpoints and the diff need the
16	// checkout: `remote` reaches it over SSH when Orca's SSH target for the server is known (its key must be
17	// in ssh-agent, since nothing can type a passphrase), and `remoteProblem` says why not otherwise.
18	export function serverHost({ environment, path, repoUrl, branch, target = null, remoteProblem = null }) {
19	  return {
20	    kind: 'server',
21	    environment,
22	    path,
23	    repo: safeRepoUrl(repoUrl),
24	    branch: branchName(branch),
25	    remote: target ? { kind: 'ssh', environment, target, path } : null,
26	    remoteProblem: target ? null : remoteProblem
27	  }
28	}
29	
30	// One POSIX shell word: the remote shell parses the command line ssh sends, so every part is quoted.
31	export function shellQuote(word) {
32	  return `'${String(word).replaceAll("'", `'\\''`)}'`
33	}
34	
35	// A login shell puts ~/.local/bin, where Entire installs, on PATH. BatchMode fails instead of prompting.
36	function sshCommand(host, argv) {
37	  const { host: address, port, user } = host.target
38	  const remote = ['bash', '-lc', 'cd -- "$1" && shift && exec "$@"', 'bash', host.path, ...argv].map(shellQuote).join(' ')
39	  return {
40	    command: 'ssh',
41	    args: [
42	      '-n', '-T', '-o', 'BatchMode=yes', '-o', 'ConnectTimeout=8',
43	      // Only a port Orca saved: an ~/.ssh/config alias may set its own, which `-p` would override.
44	      ...(port === null ? [] : ['-p', String(port)]),
45	      '--', user ? `${user}@${address}` : address, remote
46	    ]
47	  }
48	}
49	
50	// A branch as Git allows it (`git check-ref-format --branch`), or null. Orca reports it and it goes to
51	// Entire as one argument, never through a shell, so Git's rules are the only limit, plus no leading "-",
52	// which would read as a flag.
53	export function branchName(name) {
54	  if (typeof name !== 'string' || name.length === 0 || name.length > 255) return null
55	  if (/[\x00-\x20\x7f~^:?*[\\]/.test(name) || name.includes('..') || name.includes('@{') || name === '@') return null
56	  if (name.startsWith('-') || name.startsWith('/') || name.endsWith('/') || name.endsWith('.')) return null
57	  return name.split('/').every((part) => part && !part.startsWith('.') && !part.endsWith('.lock')) ? name : null
58	}
59	
60	// The remote URL comes from Orca and goes to Entire as one argument; it must not read as a flag.
61	export function safeRepoUrl(url) {
62	  return typeof url === 'string' && /^[\w.+-]+(?::\/\/|@)[^\s]{1,400}$/.test(url) && !url.startsWith('-') ? url : null
63	}
64	
65	export function entireCommand(host, args) {
66	  if (host.kind === 'wsl') {
67	    // A login shell puts ~/.local/bin on PATH; "$@" passes each argument through without re-parsing.
68	    return {
69	      command: 'wsl.exe',
70	      args: ['-d', host.distro, '--cd', host.path, '-e', 'bash', '-lc', 'exec entire "$@"', 'entire', ...args]
71	    }
72	  }
73	  // Outside any checkout, so only --repo and --branch say which repository Entire reads.
74	  if (host.kind === 'server') return { command: 'entire', args, cwd: tmpdir() }
75	  // The opt-out has to travel with the command: the desktop env stays on this side of SSH.
76	  if (host.kind === 'ssh') return sshCommand(host, ['env', 'ENTIRE_TELEMETRY_OPTOUT=1', 'entire', ...args])
77	  return { command: 'entire', args, cwd: host.path }
78	}
79	
80	export function gitCommand(host, args) {
81	  if (host.kind === 'server') throw new Error(`git runs only on ${host.environment}`)
82	  if (host.kind === 'ssh') return sshCommand(host, ['git', ...args])
83	  if (host.kind === 'wsl') return { command: 'wsl.exe', args: ['-d', host.distro, '--cd', host.path, '-e', 'git', ...args] }
84	  return { command: 'git', args, cwd: host.path }
85	}
