  // A clock that each call advances by a second: the list ends at 1 s, the first four shows (the
  // pool's width) start at once, and by the time one ends the deadline has passed.
  let clock = 0
  const { calls, run } = fakeEntire({ items: Array.from({ length: 6 }, (_, i) => ({ number: 600 - i })), trails: [] })
  const timeouts = []
  const timed = async (host, args, options) => {
    timeouts.push(options.timeoutMs)
    clock += 1000
    return run(host, args, options)
  }
  const { step, trails } = await collectTrails(local, { origin, deadline: 2500, run: timed, now: () => clock })
  assert.equal(calls.filter((args) => args[1] === 'show').length, 4)
  assert.equal(step.ok, true)
  assert.equal(step.text, 'no other open changes in this repository (2 trails not checked in time)')
  assert.deepEqual(trails, [])
  // The list got the 2.5 s left plus the grace, the shows the 1.5 s left plus the grace.
  assert.deepEqual(timeouts, [5500, 4500, 4500, 4500, 4500])

